import hashlib,json,shutil
from pathlib import Path
root=Path('evidence/development/software-clipping')
summary=json.loads((root/'verification-summary.json').read_text());audit=json.loads((root/'regression-comparison.json').read_text());regressions=json.loads((root/'regressions.json').read_text())
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
for name in ['preserve.py','finish-evidence.py','stage-audit.py']:shutil.copy2(Path('artifacts/software-clipping')/name,root/name)
value={'schemaVersion':1,'status':'owned software clipping candidate verified; strict native mirror acceptance pending','previousCandidate':regressions['previousCandidate'],'referenceRevision':'fe8a1d462fbd793d883fb92086a16aa2947e32c9',**summary,
 'sourcePixelChangeCounts':{'fewerChangedPixels':sum(r['afterChangedPixels']<r['beforeChangedPixels'] for r in audit['results']),'sameChangedPixels':sum(r['afterChangedPixels']==r['beforeChangedPixels'] for r in audit['results']),'moreChangedPixels':sum(r['afterChangedPixels']>r['beforeChangedPixels'] for r in audit['results'])},
 'geometryPassesLost':0,'exactPassesLost':0,'approvedExceptions':[],'softwareInvariantRows':32,'positionComparisonPairs':64,'ghostWholeFrameIdentityWitnesses':32,'rhiSoftwareSpecificRowsSkipped':32,
 'limitations':['47/80 desktop APIs started; none completely accepted; TV unchanged.','Strict native raster, broader generic/font/script/fractional-scale contexts and shadow calibration remain pending.','Transparent-corner descendant pointer behavior is preserved; native hit-region equivalence, physical input/display and actual readers remain pending.','Software renderer adapter uses private interfaces tied to the existing exact Qt 6.8.3 pin; Qt upgrades require revalidation.','Virtual X11/nested-Wayland and Mesa checks do not establish physical GPU/driver or device acceptance.','The new software-only text-invariance rows are skipped on RHI; RHI text-raster equivalence remains an independent unaccepted gate.','Opaque vector-outline compositing remains in the full zero-tolerance native audit; only glyph interiors and transparent-text frames have the additional byte-identity contract.','The Qt pixmap alpha defect is independently reproduced by the included public-Qt-only program; production uses an explicitly alpha-capable image with the normal Qt node dispatcher.','Capture/build provenance records preceding main plus exact dirty source hashes.','No source pin, expected image, tolerance, accepted exception, sibling, infrastructure or TV change.']}
value['files']={str(p.relative_to(root)):sha(p) for p in sorted(root.rglob('*')) if p.is_file() and p.name!='candidate.json'}
(root/'candidate.json').write_text(json.dumps(value,indent=2)+'\n')
print('Sealed',len(value['files']),'files;',json.dumps({k:v for k,v in value.items() if k not in ['files','limitations']}))
